package com.hbm.machine.radar;
import java.util.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.fml.event.lifecycle.FMLCommonSetupEvent;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class RadarContent{private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");public static final DeferredBlock<RadarBlock> BLOCK=BLOCKS.register("machine_radar",RadarBlock::new);public static final DeferredBlock<LargeRadarBlock> LARGE=BLOCKS.register("machine_radar_large",LargeRadarBlock::new);public static final DeferredBlock<RadarScreenBlock> SCREEN=BLOCKS.register("radar_screen",RadarScreenBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem("machine_radar",BLOCK),LARGE_ITEM=ITEMS.registerSimpleBlockItem("machine_radar_large",LARGE),SCREEN_ITEM=ITEMS.registerSimpleBlockItem("radar_screen",SCREEN);public static final DeferredItem<RadarLinkerItem> LINKER=ITEMS.register("radar_linker",RadarLinkerItem::new);public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<RadarBlockEntity>> ENTITY=ENTITIES.register("radar",()->BlockEntityType.Builder.of(RadarBlockEntity::new,BLOCK.get()).build(null)),LARGE_ENTITY=ENTITIES.register("radar_large",()->BlockEntityType.Builder.of((pos,state)->new RadarBlockEntity(pos,state,true),LARGE.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<RadarPort>> PORT=ENTITIES.register("radar_port",()->BlockEntityType.Builder.of(RadarPort::new,LARGE.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<RadarScreenBlockEntity>> SCREEN_ENTITY=ENTITIES.register("radar_screen",()->BlockEntityType.Builder.of(RadarScreenBlockEntity::new,SCREEN.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<RadarMenu>> MENU=MENUS.register("radar",()->new MenuType<>((IContainerFactory<RadarMenu>)RadarMenu::new,FeatureFlags.DEFAULT_FLAGS));public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);bus.addListener(RadarControl::register);bus.addListener(RadarStatePacket::register);bus.addListener((FMLCommonSetupEvent e)->e.enqueueWork(RadarConfig::load));}public static List<ItemStack> creativeStacks(String tab){return tab.equals("missile")?List.of(new ItemStack(ITEM.get()),new ItemStack(LARGE_ITEM.get()),new ItemStack(SCREEN_ITEM.get())):tab.equals("consumable")?List.of(new ItemStack(LINKER.get())):List.of();}public static ResourceLocation id(String path){return ResourceLocation.fromNamespaceAndPath("hbm",path);}private RadarContent(){}}
